#!/usr/bin/env node
/**
 * Tests for the PowerShell -EncodedCommand decoding of hooks/lib/shell-parse.js, through hooks/guard-shell.js.
 * Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test tools/guard-shell-encoded.test.mjs
 *
 * Hermetic: HOME / USERPROFILE point at a temp directory holding a fixture db-targets registry, cwd is an
 * empty temp directory.
 *
 * Generated by Claude Code at the user's request.
 */

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HOOK = join(ROOT, 'hooks', 'guard-shell.js');
const home = mkdtempSync(join(tmpdir(), 'encoded-home-'));
const cwd = mkdtempSync(join(tmpdir(), 'encoded-cwd-'));
mkdirSync(join(home, '.claude'));
writeFileSync(join(home, '.claude', 'db-targets.json'), JSON.stringify({ devHosts: ['localhost', '127.0.0.1'] }));
after(() => { for (const dir of [home, cwd]) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } } });

function run(command, tool = 'PowerShell') {
  const env = { ...process.env, HOME: home, USERPROFILE: home };
  const r = spawnSync(process.execPath, [HOOK], { input: JSON.stringify({ tool_name: tool, tool_input: { command }, cwd }), encoding: 'utf8', env });
  assert.equal(r.status, 0, 'the hook must always exit 0');
  if (!r.stdout.trim()) return 'approve';
  return JSON.parse(r.stdout).hookSpecificOutput.permissionDecision ?? 'approve';
}

const enc = (text) => Buffer.from(text, 'utf16le').toString('base64');
const PUSH = 'git push origin main --force';

test('given the plain force push, when guard-shell runs, then it asks (the reference for the encoded forms)', () => {
  // Given / When
  const decision = run(PUSH);

  // Then
  assert.equal(decision, 'ask');
});

test('given an -EncodedCommand payload of the force push, when guard-shell runs, then it asks exactly as the plain form does', () => {
  // Given
  const command = `powershell -EncodedCommand ${enc(PUSH)}`;

  // When
  const decision = run(command);

  // Then
  assert.equal(decision, run(PUSH));
});

test('given -e, -en, -enc, -encodedc and -ENCODEDCOMMAND, when guard-shell runs, then each is decoded', () => {
  // Given
  const flags = ['-e', '-en', '-enc', '-encodedc', '-ENCODEDCOMMAND'];

  for (const flag of flags) {
    // When
    const decision = run(`pwsh -NoProfile ${flag} ${enc(PUSH)}`);

    // Then
    assert.equal(decision, 'ask', flag);
  }
});

test('given a slash or a Unicode dash before EncodedCommand, when guard-shell runs, then the payload is decoded too', () => {
  // Given
  const flags = ['/EncodedCommand', '–EncodedCommand', '—enc', '−EncodedCommand'];

  for (const flag of flags) {
    // When
    const decision = run(`powershell ${flag} ${enc(PUSH)}`);

    // Then
    assert.equal(decision, 'ask', flag);
  }
});

test('given -ExecutionPolicy Bypass, -EncodedArguments and -Ep, when guard-shell runs, then none is read as the encoded flag', () => {
  // Given
  const commands = ['powershell -ExecutionPolicy Bypass -File x.ps1', `pwsh -EncodedArguments ${enc(PUSH)} -File x.ps1`, `pwsh -Ep Bypass -File x.ps1 ${enc(PUSH)}`];

  for (const command of commands) {
    // When
    const decision = run(command);

    // Then
    assert.equal(decision, 'approve', command);
  }
});

test('given pwsh, pwsh.exe, a docker exec and a bash -c around the encoded payload, when guard-shell runs, then it is decoded', () => {
  // Given
  const commands = [`pwsh -enc ${enc(PUSH)}`, `pwsh.exe -enc ${enc(PUSH)}`, `docker exec c pwsh -enc ${enc(PUSH)}`, `bash -c "pwsh -enc ${enc(PUSH)}"`];

  for (const command of commands) {
    // When
    const decision = run(command, 'Bash');

    // Then
    assert.equal(decision, 'ask', command);
  }
});

test('given a payload encoded within MAX_DEPTH and one beyond it, when guard-shell runs, then the first is decoded and the second asks', () => {
  // Given
  const nest = (levels) => { let text = 'echo hi'; for (let i = 0; i < levels; i += 1) text = `pwsh -enc ${enc(text)}`; return text; };

  // When
  const within = run(nest(2));
  const beyond = run(nest(7));

  // Then
  assert.equal(within, 'approve');
  assert.equal(beyond, 'ask');
});

test('given invalid base64 and bytes that are not valid UTF-16LE, when guard-shell runs, then it asks, not denies', () => {
  // Given
  const loneSurrogate = Buffer.from([0x00, 0xd8, 0x41, 0x00]).toString('base64');
  const oddLength = Buffer.from([0x41]).toString('base64');
  const commands = ['pwsh -enc !!!not-base64!!!', `pwsh -enc ${loneSurrogate}`, `pwsh -enc ${oddLength}`];

  for (const command of commands) {
    // When
    const decision = run(command);

    // Then
    assert.equal(decision, 'ask', command);
  }
});

test('given an encoded sqlcmd aimed at a non-dev host, when guard-shell runs, then it is denied', () => {
  // Given
  const command = `pwsh -enc ${enc('sqlcmd -S prod-host -d Orders -Q "SELECT 1"')}`;

  // When
  const decision = run(command);

  // Then
  assert.equal(decision, 'deny');
});

test('given pwsh -File, when guard-shell runs, then the -EncodedCommand handling adds no ask', () => {
  // Given
  const command = 'pwsh -NoProfile -File x.ps1';

  // When
  const decision = run(command);

  // Then
  assert.equal(decision, 'approve');
});
